<script setup lang="ts">
import { ref, computed, watch, onMounted, onUnmounted } from 'vue';
import AdminDialog from './AdminDialog.vue';
import PlatformSettings from './PlatformSettings.vue';
import UserAccessFields from './UserAccessFields.vue';
import PlatformInvitations from './PlatformInvitations.vue';
import CommunicationManagement from './modules/communication/CommunicationManagement.vue';

const props=defineProps<{communicationModule?:boolean;superAdmin?:boolean;name:string;tagline:string;logo:string|null;csrf?:string;success?:string|null;errors?:string[]}>();
type Row=Record<string,any>;
const data=ref<Row|null>(null), tab=ref(props.communicationModule||window.location.hash==='#users'?'Users':({'#settings':'Settings','#invitations':'Invitations','#communication':'Communication','#companies':'Companies'} as Record<string,string>)[window.location.hash]||'Dashboard'), editor=ref<Row|null>(null), error=ref(props.errors?.join(' ')||''), message=ref(props.success||''), busy=ref(false);
const tabs=props.communicationModule?['Users']:['Dashboard','Blogs','Website','Products','Users','Invitations','Settings','Branding'];
const invitationOpen=ref(false);const userSearch=ref(''),userStatus=ref('all'),userProduct=ref(''),userPage=ref(1);const pageSize=15;
const userRows=computed(()=>data.value?.users.filter((u:Row)=>[u.name,u.email,...(u.company_ids||[]).map((id:number)=>data.value?.companies.find((c:Row)=>c.id===id)?.name||'')].join(' ').toLowerCase().includes(userSearch.value.toLowerCase())&&(userStatus.value==='all'||!!u.is_active===(userStatus.value==='active'))&&(!userProduct.value||u.product_slugs.includes(userProduct.value)))||[]);
const userPages=computed(()=>Math.max(1,Math.ceil(userRows.value.length/pageSize)));const pagedUsers=computed(()=>userRows.value.slice((userPage.value-1)*pageSize,userPage.value*pageSize));watch([userSearch,userStatus,userProduct],()=>userPage.value=1);watch(userPages,n=>userPage.value=Math.min(userPage.value,n));
const superAdmin=computed(()=>props.superAdmin??window.portal.admin);
const navigationGroups=[{label:'Workspace',items:['Dashboard','Products',...(superAdmin.value?['Settings']:[])]},{label:'People & access',items:['Companies','Users','Invitations']},{label:'Website',items:['Blogs','Website',...(superAdmin.value?['Branding']:[])]}];
async function request(url:string,method='GET',body?:Row){
const response=await fetch(url,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});
const result=await response.json();
if(!response.ok)throw new Error(result.errors?Object.values(result.errors).flat().join(' '):result.message||'Unable to complete this action.');
return result;
}
async function load(){try{data.value=await request(props.communicationModule?'/communication/api/users':'/admin/api');}catch(e){error.value=(e as Error).message;}}
if(!props.communicationModule&&window.location.hash==='#roles')window.location.replace('/pms?section=roles');
function hashChanged(){if(window.location.hash==='#roles'){window.location.assign('/pms?section=roles');return;}const target=({'#settings':'Settings','#users':'Users','#invitations':'Invitations','#communication':'Communication','#companies':'Companies'} as Record<string,string>)[window.location.hash];if(!props.communicationModule&&target)select(target);}
onMounted(()=>{void load();window.addEventListener('hashchange',hashChanged);});
onUnmounted(()=>window.removeEventListener('hashchange',hashChanged));
function select(value:string){invitationOpen.value=false;if(!props.communicationModule)history.replaceState(null,'',location.pathname+location.search+(value==='Settings'?'#settings':value==='Users'?'#users':value==='Invitations'?'#invitations':value==='Communication'?'#communication':value==='Companies'?'#companies':value==='Roles & permissions'?'#roles':''));tab.value=value;editor.value=null;error.value='';message.value='';}
function edit(row?:Row){
error.value='';message.value='';
if(row){const copy:Row=JSON.parse(JSON.stringify(row));if(tab.value==='Users'){if(!superAdmin.value)delete copy.judibas_administrator;copy.password='';copy.canteen_role||='employee';copy.canteen_level_ids||={};copy.company_ids=copy.company_ids||[copy.company_id].filter(Boolean);copy.pms_role_ids||=[];copy.pms_department_ids||=[];if(props.communicationModule)copy.product_slugs=copy.product_slugs.filter((slug:string)=>slug==='communication');}editor.value=copy;return;}
editor.value=tab.value==='Blogs'?{title:'',slug:'',excerpt:'',body:'',published:false}:tab.value==='Users'?{name:'',email:'',password:'',is_active:true,company_id:'',company_ids:[],communication_admin:false,canteen_role:'employee',canteen_level_ids:{} as Record<string,number|string|null>,pms_role_ids:[],pms_department_ids:[],product_slugs:props.communicationModule?['communication']:[]}:{};
}
async function save(resource:string,row:Row){
busy.value=true;error.value='';message.value='';
try{const result=await request((props.communicationModule?'/communication/api/':'/admin/api/')+resource+(row.id?'/'+row.id:''),'POST',resource==='users'?{...row,company_id:row.company_ids?.[0]||null,communication_admin:row.product_slugs.includes('communication')&&!!row.communication_admin}:row);message.value=result.message;editor.value=null;await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}
}
async function remove(resource:string,row:Row){
if(!confirm(props.communicationModule?'Remove Communication access for '+row.name+'?':'Delete '+(row.title||row.name)+'? This cannot be undone.'))return;
busy.value=true;error.value='';
try{await request((props.communicationModule?'/communication/api/':'/admin/api/')+resource+'/'+row.id,'DELETE');message.value='Deleted.';await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}
}
</script>
<template>
<section class="super-admin">
<div v-if="!communicationModule" class="admin-heading"><div><p class="eyebrow">{{superAdmin?'SUPER ADMIN':'JUDIBAS ADMIN'}}</p><h1>Administration</h1><p class="muted">Manage your company website, people, and products.</p></div><a class="button" href="/">View website →</a></div>
<div class="admin-shell" :class="{'admin-shell-compact':communicationModule}"><aside v-if="!communicationModule" class="admin-navigation"><nav aria-label="Administration sections"><details v-for="group in navigationGroups" :key="group.label" open class="admin-navigation-group"><summary>{{group.label}}</summary><button v-for="item in group.items" :key="item" @click="select(item)" :class="{active:tab===item}" :aria-label="item" :aria-current="tab===item?'page':undefined"><span>{{item}}</span><span v-if="item==='Users'&&data" class="admin-nav-count">{{data.users.length}}</span></button></details></nav></aside><div class="admin-main">
<p v-if="error" class="notice admin-error" role="alert">{{ error }}</p><p v-if="message" class="notice" role="status">{{ message }}</p><p v-if="!data&&!error" class="muted">Loading administration…</p>
<template v-if="data">
<div v-if="tab==='Dashboard'"><h2>Your workspace at a glance</h2><div class="admin-stats"><button @click="select('Blogs')"><strong>{{ data.blogs.length }}</strong><span>Articles</span></button><button @click="select('Products')"><strong>{{ data.products.length }}</strong><span>Registered products</span></button><button @click="select('Users')"><strong>{{ data.users.length }}</strong><span>Employee accounts</span></button><a href="/products/communication"><strong>{{ data.companies.length }}</strong><span>Open Communication product</span></a></div><p class="muted">Use the sections above to publish content, manage product presentation, and assign employee access.</p></div>
<template v-if="tab==='Blogs'">
<div class="admin-section-heading"><h2>Blog articles</h2><button class="button primary" @click="edit()">New article</button></div>
<form v-if="editor" @submit.prevent="save('blogs',editor)" class="admin-editor"><h3>{{ editor.id?'Edit article':'New article' }}</h3><label>Title<input v-model="editor.title" required maxlength="200"></label><label>URL slug<input v-model="editor.slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" placeholder="company-update"></label><label>Excerpt<textarea v-model="editor.excerpt" maxlength="1000"></textarea></label><label>Article text<textarea v-model="editor.body" required rows="10"></textarea></label><label class="check"><input type="checkbox" v-model="editor.published">Publish article on the website</label><div class="editor-actions"><button class="button primary" :disabled="busy">Save article</button><button type="button" class="button" :disabled="busy" @click="editor=null">Cancel</button></div></form>
<div class="admin-list"><p v-if="!data.blogs.length" class="empty-state">No articles yet. Create your first company update.</p><article v-for="post in data.blogs" :key="post.id"><div><strong>{{ post.title }}</strong><p class="muted">/blog/{{ post.slug }} · {{ post.published?'Published':'Draft' }}</p></div><div class="row-actions"><a v-if="post.published" :href="'/blog/'+post.slug">View</a><button @click="edit(post)">Edit</button><button :disabled="busy" @click="remove('blogs',post)">Delete</button></div></article></div>
</template>
<template v-if="tab==='Website'">
<h2>Website content</h2><form @submit.prevent="save('announcement',data.announcement)" class="admin-editor"><h3>Homepage announcement</h3><label>Title<input v-model="data.announcement.title" required maxlength="100"></label><label>Message<input v-model="data.announcement.text" required maxlength="250"></label><label>Link within this website<input v-model="data.announcement.url" required placeholder="/about"></label><button class="button primary" :disabled="busy">Save announcement</button></form>
<h3>Company pages</h3><form v-if="editor" @submit.prevent="save('pages',editor)" class="admin-editor"><h3>Edit {{ editor.slug }}</h3><label>Page title<input v-model="editor.title" required></label><label>Introduction<textarea v-model="editor.intro"></textarea></label><label>Page text<textarea v-model="editor.body" required rows="10"></textarea></label><div class="editor-actions"><button class="button primary" :disabled="busy">Save page</button><button type="button" class="button" :disabled="busy" @click="editor=null">Cancel</button></div></form>
<div class="admin-list"><article v-for="(page,slug) in data.pages" :key="slug"><div><strong>{{ page.title }}</strong><p class="muted">/{{ slug }}</p></div><button @click="edit({...page,slug})">Edit page</button></article></div>
</template>
<template v-if="tab==='Products'">
<h2>Product catalogue</h2><p class="muted">Developers register products. Manage their public presentation here.</p>
<form v-if="editor" @submit.prevent="save('products',editor)" class="admin-editor"><h3>Edit {{ editor.name }}</h3><label>Display name<input v-model="editor.name" required maxlength="100"></label><label>Description<textarea v-model="editor.description" required></textarea></label><label>Icon symbol (optional)<input v-model="editor.icon" maxlength="16" placeholder="Leave blank for the default icon"></label><label>Icon colour<input type="color" v-model="editor.color"></label><label>Display order<input type="number" v-model.number="editor.display_order" min="0" max="10000" required></label><label class="check"><input type="checkbox" v-model="editor.visible">Visible on the website</label><div class="editor-actions"><button class="button primary" :disabled="busy">Save product</button><button type="button" class="button" :disabled="busy" @click="editor=null">Cancel</button></div></form>
<div class="admin-list"><article v-for="product in data.products" :key="product.slug"><div><strong>{{ product.name }}</strong><p class="muted">{{ product.visible?'Visible':'Hidden' }} · Order {{ product.display_order }}</p></div><button @click="edit(product)">Edit product</button></article></div>
</template>
<template v-if="tab==='Users'">
<div class="admin-section-heading"><h2>{{communicationModule?'Communication users':'Employees and access'}}</h2><button v-if="!communicationModule" class="button primary" @click="select('Invitations');invitationOpen=true">Invite employee</button><button class="button" @click="edit()">New employee</button></div>
<AdminDialog v-if="editor" :title="editor.id?'Edit employee':'New employee'" subtitle="Account details and product access, managed in one place." :busy="busy" @close="editor=null"><form @submit.prevent="save('users',editor)" class="admin-editor"><div class="admin-form-grid"><label>Name<input v-model="editor.name" required maxlength="100"></label><fieldset v-if="communicationModule"><legend>Companies (select one or more)</legend><div class="comm-invite-companies"><label class="check" v-for="company in data.companies" :key="company.id"><input type="checkbox" v-model="editor.company_ids" :value="company.id">{{company.name}}</label></div><small>The employee joins every selected company community.</small></fieldset><label>Email<input type="email" v-model="editor.email" required autocomplete="off"></label><label>{{ editor.id?'New password (leave blank to keep current password)':'Password' }}<input type="password" v-model="editor.password" :required="!editor.id" minlength="12" autocomplete="new-password"><small>At least 12 characters.</small></label><label class="check"><input type="checkbox" v-model="editor.is_active">Account active</label><label v-if="superAdmin&&!communicationModule" class="check"><input type="checkbox" v-model="editor.judibas_administrator"><span>Judibas Admin<small>Manage all products and employees. Private-chat review and shared credentials stay with Super Admin.</small></span></label><template v-if="!communicationModule&&editor.product_slugs.includes('projects')"><label>Surname<input v-model="editor.surname" maxlength="255"></label><label>Designation<input v-model="editor.designation" maxlength="255"></label></template></div><UserAccessFields v-if="!communicationModule" :value="editor" :data="data"/><template v-else><fieldset><legend>Products this employee can access</legend><label class="check" v-for="product in data.products" :key="product.slug"><input type="checkbox" :value="product.slug" v-model="editor.product_slugs">{{product.name}}</label></fieldset><label class="check"><input type="checkbox" v-model="editor.communication_admin">Communication administrator</label></template><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><div class="editor-actions"><button class="button primary" :disabled="busy">{{busy?'Saving...':'Save employee'}}</button><button type="button" class="button" :disabled="busy" @click="editor=null">Cancel</button></div></form></AdminDialog>
<div class="admin-user-summary"><span><strong>{{data.users.length}}</strong> employees</span><span><i class="admin-status-dot"></i><strong>{{data.users.filter((u:Row)=>u.is_active).length}}</strong> active accounts</span></div>
<div class="admin-table-card"><div class="admin-filterbar"><label class="admin-search-field"><span>Search employees</span><input v-model="userSearch" type="search" placeholder="Search by name, email or company..."></label><label><span>Status</span><select v-model="userStatus"><option value="all">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select></label><label><span>Product</span><select v-model="userProduct"><option value="">All products</option><option v-for="product in data.products" :key="product.slug" :value="product.slug">{{product.name}}</option></select></label></div>
<div class="admin-table-scroll"><table class="admin-user-table"><thead><tr><th>Employee</th><th>Companies</th><th>Products</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="user in pagedUsers" :key="user.id"><td><div class="admin-person"><span class="admin-avatar">{{user.name.slice(0,2).toUpperCase()}}</span><div><strong>{{user.name}}</strong><small>{{user.email}}</small><span v-if="user.judibas_administrator" class="admin-chip admin-product-chip">Judibas Admin</span></div></div></td><td><div class="admin-chip-list"><span v-for="id in user.company_ids||[user.company_id].filter(Boolean)" :key="id" class="admin-chip">{{data.companies.find((c:Row)=>c.id===id)?.name||'Company'}}</span><span v-if="!(user.company_ids||[user.company_id].filter(Boolean)).length" class="muted">Unassigned</span></div></td><td><div class="admin-chip-list"><span v-if="user.judibas_administrator" class="admin-chip admin-product-chip">All products</span><span v-for="slug in (user.judibas_administrator?[]:user.product_slugs)" :key="slug" class="admin-chip admin-product-chip">{{data.products.find((p:Row)=>p.slug===slug)?.name||slug}}</span><span v-if="!user.judibas_administrator&&!user.product_slugs.length" class="muted">No access assigned</span></div></td><td><span class="admin-status" :class="user.is_active?'is-active':'is-inactive'">{{user.is_active?'Active':'Inactive'}}</span></td><td><div v-if="superAdmin||!user.judibas_administrator" class="row-actions"><button class="button" :aria-label="'Edit '+user.name" @click="edit(user)">Edit</button><button class="button admin-danger" :disabled="busy" :aria-label="(communicationModule?'Remove access for ':'Delete ')+user.name" @click="remove('users',user)">{{communicationModule?'Remove access':'Delete'}}</button></div></td></tr><tr v-if="!userRows.length"><td colspan="5" class="empty-state">{{data.users.length?'No employees match these filters.':'No employee accounts yet. Create an account or send an invitation.'}}</td></tr></tbody></table></div>
<div class="admin-pagination"><span>{{userRows.length}} matching employees</span><div><button class="button" :disabled="userPage<=1" @click="userPage--">Previous</button><span>{{userPage}} / {{userPages}}</span><button class="button" :disabled="userPage>=userPages" @click="userPage++">Next</button></div></div></div>
</template>

<section v-if="tab==='Communication'&&!communicationModule"><div class="admin-section-heading"><div><h2>Communication management</h2><p class="muted">Manage groups, community announcements and status updates. Shared companies, users and invitations are under People & access.</p></div><a class="button primary" href="/communication">Open chats</a></div><div class="editor-actions"><a class="button" href="/communication?section=Status">Status updates</a><a v-if="superAdmin" class="button" href="/communication?action=review">Review conversations</a><a v-if="superAdmin" class="button" href="/communication?action=audit">Review log</a></div><CommunicationManagement view="communities" :csrf="csrf"/></section>
<section v-if="tab==='Companies'&&!communicationModule"><CommunicationManagement view="companies" :csrf="csrf" @changed="load"/></section>
<PlatformInvitations v-if="tab==='Invitations'&&!communicationModule" :csrf="csrf" :data="data" :start-open="invitationOpen"/>
<PlatformSettings v-if="tab==='Settings'&&!communicationModule&&superAdmin" :csrf="csrf"/>
<template v-if="tab==='Branding'&&superAdmin"><h2>Branding</h2><form action="/admin/settings" method="post" enctype="multipart/form-data" class="settings-form"><input type="hidden" name="_token" :value="csrf"><label>Project name<input name="name" :value="name" maxlength="80" required></label><label>Homepage introduction<input name="tagline" :value="tagline" maxlength="160" required></label><label>Company logo<input name="logo" type="file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG or WebP. Up to 2 MB.</small></label><img v-if="logo" :src="logo" alt="Current company logo" class="admin-logo"><button class="button primary">Save branding</button></form></template>
</template>

</div></div>
</section>
</template>